UPDATE ui.dashboardquery SET
vcdashboardquery = 'with d1 as (select case when vcrolename = ''CUB Analyst'' then ''CUB_RiskNotification'' when vcrolename = ''USFB Analyst'' then ''USFB_RiskNotification'' else ''ALL'' end as role from ui.webuser wu left join ui.userrolemap urm on urm.iuserid = wu.iuserid left join ui.roledesc rd on rd.iroleid = urm.iroleid where wu.iuserid = :loggedinuser) SELECT string_agg(DISTINCT grp.name_, '', '') as "Group Name", task.assignee_ as "Analyst Name", count(distinct CASE WHEN DATE_PART(''day'', current_timestamp -  CASE WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  oplog.timestamp_ is null THEN task.create_time_ ELSE null END ) > 30 THEN task.proc_inst_id_ ELSE null END) as "Above 30 days", count(distinct CASE WHEN DATE_PART(''day'', current_timestamp -  CASE WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  oplog.timestamp_ is null THEN task.create_time_ ELSE null END ) between 20 and 30 THEN task.proc_inst_id_ ELSE null END) as "30 days to 20 days", count(distinct CASE WHEN DATE_PART(''day'', current_timestamp -  CASE WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  oplog.timestamp_ is null THEN task.create_time_ ELSE null END ) between 10 and 20 THEN task.proc_inst_id_ ELSE null END) as "20 days to 10 days", count(distinct CASE WHEN DATE_PART(''day'', current_timestamp -  CASE WHEN  oplog.timestamp_ is not null THEN oplog.timestamp_ WHEN  oplog.timestamp_ is null THEN task.create_time_ ELSE null END ) < 10 THEN task.proc_inst_id_ ELSE null END) as "below 10 days" FROM camunda.act_ru_task task right join camunda.act_re_procdef pdef on task.proc_def_id_ = pdef.id_ full outer join camunda.act_hi_identitylink oplog on oplog.id_ = (select id_ from camunda.act_hi_identitylink where task_id_ = task.id_ and type_ = ''assignee'' and user_id_ = task.assignee_ order by timestamp_ desc limit 1) right join camunda.act_id_membership memb on task.assignee_ = memb.user_id_ right join camunda.act_hi_identitylink idl on idl.task_id_ = task.id_ and idl.type_= ''candidate'' left join camunda.act_id_group grp on grp.id_ = idl.group_id_ and grp.id_ = memb.group_id_ where task.assignee_ is not null and (''ALL'' = (select role from d1) or pdef.key_  = (select role from d1)) group by task.assignee_ order by string_agg(DISTINCT grp.name_, '', '') asc

'::text WHERE
idashboardqueryid = 59;




