t full outer join camunda.act_hi_varinst actionvar on actionvar.proc_inst_id_ = hiproinst.proc_inst_id_ and actionvar.name_ = ''Action'' full outer join camunda.act_hi_taskinst closedby on closedby.id_ = (select id_ from camunda.act_hi_taskinst where proc_inst_id_ = hiproinst.proc_inst_id_ order by end_time_ desc limit 1) full outer join camunda.act_hi_varinst accountid on accountid.proc_inst_id_ = hiproinst.proc_inst_id_ and accountid.name_ = ''accountid'' full outer join camunda.act_hi_varinst riskscore on riskscore.proc_inst_id_ = hiproinst.proc_inst_id_ and riskscore.name_ = ''RiskScore'' full outer join camunda.act_hi_varinst  TransactionAmount on TransactionAmount.proc_inst_id_ = hiproinst.proc_inst_id_ and TransactionAmount.name_ = ''TransactionAmount'' full outer join camunda.act_hi_varinst triggeredtype  on triggeredtype.proc_inst_id_ = hiproinst.proc_inst_id_ and triggeredtype.name_ = ''triggeredtype'' full outer join camunda.act_hi_varinst  Txn on Txn.proc_inst_id_ = hiproinst.proc_inst_id_ and Txn.name_ = ''Transaction'' full outer join camunda.act_ge_bytearray Txnorg on Txnorg.id_ = Txn.bytearray_id_ full outer join camunda.act_hi_varinst rulename on rulename.proc_inst_id_ = hiproinst.proc_inst_id_ and rulename.name_ = ''failedRules'' full outer join camunda.act_id_user userinfo on userinfo.id_ = closedby.assignee_ where cast(hiproinst.start_time_ as date) between cast(:StartDate as date) and cast(:EndDate as date)-1 and hiproinst.state_ = ''COMPLETED'' and hiproinst.proc_def_key_ not in ( ''invoice'', ''ReviewInvoice'',''Orchestrator'', ''Sanctions'') and hiproinst.proc_def_key_ = :CaseType"
    }
  }'::text WHERE
idashboardqueryid = 73;



