UPDATE ui.dashboardquery SET
vcdashboardquery = 'with d1 as (select case when vcrolename = ''CUB Analyst'' then ''CUB_RiskNotification'' when vcrolename = ''USFB Analyst'' then ''USFB_RiskNotification'' else ''ALL'' end as role from ui.webuser wu left join ui.userrolemap urm on urm.iuserid = wu.iuserid left join ui.roledesc rd on rd.iroleid = urm.iroleid where wu.iuserid = :loggedinuser ) SELECT ''All Cases'' AS "label", ''All'' AS "value" union all (select name_ as "label", key_ as "value" FROM camunda.act_re_procdef pdef where (''ALL'' = (select role from d1) or key_  = (select role from d1)) group by key_, name_ order by name_ )'::text WHERE
idashboardqueryid = 61;